// Validate run-failed event payload
const payload = $json.body || $json;

// Payload size limit: max 50KB
const rawString = JSON.stringify(payload);
if (rawString.length > 51200) {
  return [{
    json: {
      is_valid: false,
      error: 'Payload size limit exceeded (maximum 50KB allowed)'
    }
  }];
}

const run_id = (payload.run_id || '').trim();
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!run_id || !uuidRegex.test(run_id)) {
  return [{
    json: {
      is_valid: false,
      error: 'Invalid or missing run_id (must be a valid UUID)'
    }
  }];
}

const event_type = payload.event_type || payload.status || 'RUN_FAILED';
if (event_type !== 'RUN_FAILED' && event_type !== 'failed') {
  return [{
    json: {
      is_valid: false,
      error: 'Invalid event_type (expected RUN_FAILED or failed)'
    }
  }];
}

const error_message = payload.error_message || payload.error || 'Unknown runtime error occurred';
const correlation_id = payload.correlation_id || ('corr-' + Math.random().toString(36).substring(2, 15));
const idempotency_key = payload.idempotency_key || ('failed:' + run_id);

return [{
  json: {
    is_valid: true,
    run_id,
    event_type,
    error_message,
    correlation_id,
    idempotency_key,
    failed_at: payload.failed_at || new Date().toISOString()
  }
}];

// Format Incident Alert for on-call engineers
const eventsResponse = $json;
const validation = $('Validate Failure Event').first().json;

const items = Array.isArray(eventsResponse.items) ? eventsResponse.items : [];
const recentEvents = items.slice(0, 5).map(e => `- [${e.event_type}] ${e.actor}: ${JSON.stringify(e.payload || {})}`).join('\n');

const formattedAlert = `🚨 **AgentOps Failure Incident Alert**\n\n` +
  `**Run ID:** \`${validation.run_id}\`\n` +
  `**Correlation ID:** \`${validation.correlation_id}\`\n` +
  `**Severity:** CRITICAL\n` +
  `**Error Message:**\n${validation.error_message}\n\n` +
  `**Recent Audit Events:**\n${recentEvents || 'No audit events recorded'}\n\n` +
  `*Dispatched via AgentOps n8n Incident Pipeline*`;

return [{
  json: {
    notification_type: 'RUN_FAILED',
    severity: 'CRITICAL',
    run_id: validation.run_id,
    correlation_id: validation.correlation_id,
    idempotency_key: validation.idempotency_key,
    error_summary: validation.error_message,
    recent_events_count: items.length,
    formatted_alert: formattedAlert,
    status: 'ALERTED'
  }
}];
